  'page.bgRemover.sub': { en: 'AI-powered background removal — 100% in your browser, no uploads.', ar: 'إزالة الخلفية بالذكاء الاصطناعي — 100% في متصفحك.', ur: 'AI سے پس منظر ہٹائیں — 100% آپ کے براؤزر میں۔', hi: 'AI से बैकग्राउंड हटाएं — 100% ब्राउज़र में।', es: 'Eliminación de fondo con IA — 100% en tu navegador.', fr: 'Suppression de fond par IA — 100% dans votre navigateur.', de: 'KI-gestützte Hintergrundentfernung — 100% in Ihrem Browser.', zh: 'AI驱动的背景去除 — 100%在浏览器中完成。', ja: 'AI背景除去 — 100%ブラウザ内で。', ko: 'AI 배경 제거 — 100% 브라우저에서.', tr: 'AI ile arka plan kaldırma — 100% tarayıcınızda.', ru: 'Удаление фона с помощью ИИ — 100% в браузере.', it: 'Rimozione sfondo con IA — 100% nel tuo browser.', nl: 'AI-achtergrondverwijdering — 100% in je browser.', id: 'Penghapusan latar belakang AI — 100% di browser.', th: 'ลบพื้นหลังด้วย AI — 100% ในเบราว์เซอร์', vi: 'Xóa nền bằng AI — 100% trong trình duyệt.', bn: 'AI ব্যাকগ্রাউন্ড সরানো — 100% ব্রাউজারে।', sw: 'Kuondoa mandhari kwa AI — 100% kwenye kivinjari.' },
  'page.ocrPdf.h1a': { en: 'OCR — Extract Text from', ar: 'OCR — استخراج النص من', ur: 'OCR — متن نکالیں', hi: 'OCR — टेक्स्ट निकालें', es: 'OCR — Extraer texto de', fr: 'OCR — Extraire le texte de', de: 'OCR — Text extrahieren aus', zh: 'OCR — 从扫描PDF中提取文字', ja: 'OCR — スキャンPDFからテキスト抽出', ko: 'OCR — 스캔 PDF에서 텍스트 추출', tr: 'OCR — Taranan PDF\'den metin çıkar', ru: 'OCR — Извлечь текст из', it: 'OCR — Estrai testo da', nl: 'OCR — Tekst extraheren uit', id: 'OCR — Ekstrak teks dari', th: 'OCR — ดึงข้อความจาก', vi: 'OCR — Trích xuất văn bản từ', bn: 'OCR — টেক্সট বের করুন', sw: 'OCR — Toa maandishi kutoka' },
